def solve():
    memo = {}

    def get_max_tiles(segments, is_alice_turn):
        # segments: tuple of lengths >= 2
        # is_alice_turn: True if Alice's turn (Alice wants to MINIMIZE tiles)
        # is_alice_turn: False if Bob's turn (Bob wants to MAXIMIZE tiles)

        # Sort segments to canonicalize state
        segments = tuple(sorted([s for s in segments if s >= 2]))
        state = (segments, is_alice_turn)

        if state in memo:
            return memo[state]

        if not segments:
            return 0

        if is_alice_turn:
            # Alice wants to minimize total tiles
            # She chooses a move that leads to the minimum tiles
            best_tiles = float('inf')
            for i, s in enumerate(segments):
                for j in range(s - 1):
                    s1 = j
                    s2 = s - j - 2
                    new_segments = list(segments)
                    new_segments.pop(i)
                    if s1 >= 2: new_segments.append(s1)
                    if s2 >= 2: new_segments.append(s2)

                    res = 1 + get_max_tiles(tuple(new_segments), False)
                    if res < best_tiles:
                        best_tiles = res

            # If no move is possible, this is not possible because segments is not empty.
            # But let's handle it just in case.
            if best_tiles == float('inf'):
                best_tiles = 0
        else:
            # Bob wants to maximize total tiles
            best_tiles = -1
            for i, s in enumerate(segments):
                for j in range(s - 1):
                    s1 = j
                    s2 = s - j - 2
                    new_segments = list(segments)
                    new_segments.pop(i)
                    if s1 >= 2: new_segments.append(s1)
                    if s2 >= 2: new_segments.append(s2)

                    res = 1 + get_max_tiles(tuple(new_segments), True)
                    if res > best_tiles:
                        best_tiles = res

            if best_tiles == -1:
                best_tiles = 0

        memo[state] = best_tiles
        return best_tiles

    # Alice's goal is to maximize uncovered squares = N - 2 * (number of tiles).
    # This is equivalent to Alice minimizing the number of tiles.
    # Bob wants to minimize uncovered squares = N - 2 * (number of tiles).
    # This is equivalent to Bob maximizing the number of tiles.

    # Let's test some small n.
    results = []
    for n in range(1, 15):
        memo = {}
        tiles = get_max_tiles((n,), True)
        results.append(n - 2 * tiles)
    print(results)

